  'Naar prullenbak': 'Çöp kutusuna taşı',
  'Deze presentatie staat ook op een andere plek:':
      'Bu sunum başka bir yerde de bulunuyor:',
  '"Oci" verwijst naar de ocicat, het kattenras van de katten van Brenno de Winter. "Deck" is het Engelse woord voor een diaset. OciDeck maakt van eenvoudige tekst een verzorgde presentatie.':
      '"Oci", Brenno de Winter\'ın kedilerinin ırkı olan ocicat\'e gönderme yapar. "Deck" ise İngilizcede slayt destesi anlamına gelir. OciDeck, basit metinden özenli bir sunum oluşturur.',
  'Adressen': 'Adresler',
  'Bestuur': 'Yönetim kurulu',
  'Beveiliging': 'Güvenlik',
  'Brenno de Winter (voorzitter), Jan Klopper (secretaris) en Astrid Oosenbrug (penningmeester).':
      'Brenno de Winter (başkan), Jan Klopper (sekreter) ve Astrid Oosenbrug (sayman).',
  'Contact': 'İletişim',
  'De katten van Brenno': 'Brenno\'nun kedileri',
  'De mascottes van OciDeck en verwante projecten zijn de ocicats van Brenno de Winter.':
      'OciDeck\'in ve ilgili projelerin maskotları, Brenno de Winter\'ın ocicat kedileridir.',
  'De stichting is op 23 oktober 2025 bij notariële akte opgericht te Leeuwarden en heeft haar statutaire zetel in Noordwijk.':
      'Vakıf, 23 Ekim 2025\'te Leeuwarden\'de noter senediyle kuruldu ve resmî merkezi Noordwijk\'tedir.',
  'Deze instellingen bepalen wat OciDeck vanaf het internet mag laden en welke sporen op dit apparaat achterblijven. Ze staan los van je privacyverklaring en toestemming, die je bij "Licentie en Privacy" vindt.':
      'Bu ayarlar, OciDeck\'in internetten neleri yükleyebileceğini ve bu cihazda hangi izlerin kalacağını belirler. Bu ayarlar, "Lisans ve Gizlilik" bölümünde bulacağınız gizlilik bildiriminden ve rızadan bağımsızdır.',
  'Doelstellingen van de stichting:\n\n•  Opensource-software en -hardware voor veilige digitale infrastructuren stimuleren.\n•  Transparantie en reproduceerbaarheid in beveiligingsprocessen bevorderen.\n•  Onderzoek, trainingen en activiteiten rond digitale weerbaarheid organiseren.\n•  Burgers, bedrijven, overheid en maatschappelijke organisaties met elkaar verbinden.':
      'Vakfın amaçları:\n\n•  Güvenli dijital altyapılar için açık kaynaklı yazılım ve donanımı teşvik etmek.\n•  Güvenlik süreçlerinde şeffaflığı ve yeniden üretilebilirliği geliştirmek.\n•  Dijital dayanıklılık üzerine araştırma, eğitim ve etkinlikler düzenlemek.\n•  Vatandaşları, şirketleri, kamu kurumlarını ve sivil toplum kuruluşlarını birbirine bağlamak.',
  'E-mail': 'E-posta',
  'Kernwaarden: veiligheid, vrijheid en openheid, soevereiniteit, integriteit, kennisdeling, betrouwbaarheid, menselijkheid, luisteren en verbinden, "just culture" en duurzaamheid.':
      'Temel değerler: güvenlik, özgürlük ve açıklık, egemenlik, dürüstlük, bilgi paylaşımı, güvenilirlik, insanilik, dinleme ve bağ kurma, "just culture" ve sürdürülebilirlik.',
  'Licentie en Privacy': 'Lisans ve Gizlilik',
  'Mascotte van MIAUW.': 'MIAUW\'un maskotu.',
  'Mascotte van OpenKAT.': 'OpenKAT\'ın maskotu.',
  'Mascotte van de checklisttool.': 'Kontrol listesi aracının maskotu.',
  'OciDeck wordt uitgegeven door Stichting LibreKAT. De stichting werkt aan een veiligere digitale samenleving via open, controleerbare informatiebeveiliging, met de nadruk op kennisdeling, community-vorming en het ondersteunen van opensource-oplossingen.':
      'OciDeck, Stichting LibreKAT tarafından yayımlanır. Vakıf; bilgi paylaşımına, topluluk oluşturmaya ve açık kaynaklı çözümlerin desteklenmesine ağırlık vererek açık ve denetlenebilir bilgi güvenliği yoluyla daha güvenli bir dijital toplum için çalışır.',
  'Over OciDeck': 'OciDeck hakkında',
  'Telefoon': 'Telefon',
  'Uitgever: Stichting LibreKAT': 'Yayımcı: Stichting LibreKAT',
  'Verzorgde presentaties uit eenvoudige tekst — vrij, controleerbaar en met je gegevens op je eigen apparaat.':
      'Basit metinden özenli sunumlar — özgür, denetlenebilir ve verileriniz kendi cihazınızda.',
  'Waar komt de naam vandaan?': 'Adı nereden geliyor?',
  'Website van de stichting': 'Vakfın web sitesi',
  'Opgeslagen als download in je map met downloads.':
      'İndirilenler klasörünüze indirme olarak kaydedildi.',
  'Afronden & verzegelen': 'Sonlandır & mühürle',
  'Verzegelen': 'Mühürle',
