  'Getypte handtekening': 'Yazılı imza',
  'Deze presentatie is afgerond en verzegeld en kan niet worden bewerkt.':
      'Bu sunum sonlandırıldı ve mühürlendi; artık düzenlenemez.',
  'Integriteit intact': 'Bütünlük korunuyor',
  'Gewijzigd na afronden': 'Sonlandırmadan sonra değiştirildi',
  'Verzegeld met SHA-512. De inhoud komt overeen met het zegel.':
      'SHA-512 ile mühürlendi. İçerik mühürle uyuşuyor.',
  'De inhoud wijkt af van het zegel — het bestand is na het afronden gewijzigd.':
      'İçerik mühürden farklı — dosya sonlandırmadan sonra değiştirilmiş.',
  'Presentatie afgerond en verzegeld.': 'Sunum sonlandırıldı ve mühürlendi.',
  'Een tussenkop die een nieuw deel van de presentatie aankondigt. Houd het kort. Voeg via de afbeeldingsbibliotheek een achtergrondbeeld toe.':
      'Sunumun yeni bir bölümünü duyuran bir ara başlık. Kısa tutun. Görsel kitaplığından bir arka plan görseli ekleyin.',
  'Bronnen doorzoeken…': 'Kaynaklar aranıyor…',
  'Niet doorzocht': 'Aranmadı',
  'Deze controle draait niet in de webversie: gezichtsherkenning vergt een systeembibliotheek die de browser niet heeft. Gebruik de desktopversie om afbeeldingen op gezichten na te kijken.':
      'Bu denetim web sürümünde çalışmaz: yüz tanıma, tarayıcıda bulunmayan bir sistem kitaplığı gerektirir. Görselleri yüz açısından denetlemek için masaüstü sürümünü kullanın.',
  'Het token heeft lees- en schrijfrechten op de repository nodig. Gitea en Forgejo kennen geen server-side zoeken; OciDeck zoekt lokaal.':
      'Token\'ın depo üzerinde okuma ve yazma izinleri olmalıdır. Gitea ve Forgejo sunucu tarafında arama sunmaz; OciDeck yerel olarak arar.',
  'Het token heeft de repo-scope nodig (of fijnmazig: Contents lezen en schrijven).':
      'Token\'ın repo kapsamına ihtiyacı vardır (veya ince ayarlı: Contents okuma ve yazma).',
  'Het token heeft read_repository, write_repository en read_api nodig. Server-side zoeken vereist Advanced- of Exact Search.':
      'Token için read_repository, write_repository ve read_api gerekir. Sunucu tarafında arama, Advanced veya Exact Search gerektirir.',
  'Snelle server-zoekopdracht — door indexeringsvertraging kan een net gewijzigd deck ontbreken.':
      'Hızlı sunucu araması — indeksleme gecikmesi nedeniyle yeni değiştirilmiş bir sunum eksik kalabilir.',
  'Media blijft niet bewaard in een los .md-bestand':
      'Medya, tek başına bir .md dosyasında saklanmaz',
  'Afbeeldingen, video en audio die je in dit tabblad koos, leven alleen in het geheugen. Een los .md-bestand bewaart ze niet — bij heropenen zijn ze weg. Exporteer als .ocideck-pakket om het beeld mee te nemen.':
      'Bu sekmede seçtiğiniz görseller, video ve ses yalnızca bellekte bulunur. Tek başına bir .md dosyası bunları saklamaz — yeniden açtığınızda kaybolurlar. Medyayı da yanınızda götürmek için .ocideck paketi olarak dışa aktarın.',
  'Media verwijderd om privacyredenen': 'Gizlilik nedeniyle medya kaldırıldı',
  'Afbeeldingen door AI laten taggen?':
      'Görseller yapay zekâ ile etiketlensin mi?',
  'afbeeldingen gaan naar': 'görsel şuraya gönderilir',
  'een model op dit apparaat': 'bu cihazdaki bir model',
  'Doorgaan': 'Devam et',
  'Ontdekkingen': 'Keşifler',
  'Wat is gevonden': 'Ne bulundu',
  'Soort': 'Tür',
  'Dagen onopgemerkt': 'Fark edilmeden geçen gün',
  'Ontdekking toevoegen': 'Keşif ekle',
  'Ontdekking verwijderen': 'Keşfi kaldır',
  'Kop van de slide': 'Slaydın başlığı',
  'dagen onopgemerkt': 'gün fark edilmeden',
  'Nog geen blootstelling ingevuld — de slide toont dan geen kop, alleen de lijst.':
      'Henüz maruz kalma süresi girilmedi — slayt bu durumda başlık göstermez, yalnızca listeyi gösterir.',
  'Zes ontdekkingen is het maximum; wie er meer noemt maakt een bijlage in plaats van een slide.':
      'En fazla altı keşif; daha fazlasını sayan, slayt yerine bir ek hazırlar.',
  'Laat de dagen leeg als de eerste blootstelling onbekend is; de slide zegt dan "onbekend" in plaats van nul. Een lege eigenaar leest als "geen eigenaar" en valt rood op.':
      'İlk maruz kalma bilinmiyorsa gün sayısını boş bırakın; slayt o zaman sıfır yerine "bilinmiyor" der. Boş bir sahip alanı "sahibi yok" olarak okunur ve kırmızıyla dikkat çeker.',
  'Wat de scan vond dat niemand wist te hebben. Per ontdekking hoe lang die onopgemerkt bereikbaar was en wie hem nu bezit; de langste blootstelling is de kop.':
      'Taramanın bulduğu, kimsenin sahip olduğunu bilmediği şeyler. Her keşif için ne kadar süre fark edilmeden erişilebilir kaldığı ve şu anda kime ait olduğu; en uzun maruz kalma başlığı oluşturur.',
