  'Kleurt een cel met een datum van vóór vandaag rood. OciDeck kijkt naar de dag waarop u presenteert, dus een deck dat maanden later terugkomt markeert zichzelf. Alleen jjjj-mm-dd telt als datum. Staat standaard uit.':
      'Bugünden önceki bir tarih içeren hücreyi kırmızıya boyar. OciDeck sunum yaptığınız günü esas alır, dolayısıyla aylar sonra tekrar açılan bir sunum kendini işaretler. Yalnızca yyyy-aa-gg bir tarih sayılır. Varsayılan olarak kapalıdır.',
