  'Een overzicht draagt hoogstens acht soorten; meer is een inventarislijst en geen overzicht.':
      'Bir genel bakış en fazla sekiz tür taşır; fazlası genel bakış değil, envanter listesi olur.',
  'Een deelgetal is groter dan het totaal van zijn soort. De slide toont het zoals ingevuld — controleer de bron.':
      'Bir alt sayı, kendi türünün toplamından büyük. Slayt bunu girildiği gibi gösterir — kaynağı denetleyin.',
  'De drie laatste zijn deelverzamelingen van het gevonden aantal; OciDeck telt niets zelf, de cijfers komen uit uw scan.':
      'Son üçü, bulunan sayının alt kümeleridir; OciDeck kendisi hiçbir şey saymaz, rakamlar sizin taramanızdan gelir.',
  'Het aanvalsoppervlak per soort object: hoeveel er zijn, hoeveel er werk kosten, wat nieuw is en wat niemand bezit. Dat laatste is meestal het gesprek.':
      'Nesne türüne göre saldırı yüzeyi: kaç tane var, kaçı iş gerektiriyor, ne yeni ve neyin sahibi yok. Sonuncusu genelde asıl konudur.',
