  'Vorige rapportage': 'Önceki rapor',
  'Een scorecard toont hoogstens vijf cijfers; meer leest niet meer als een oordeel.':
      'Bir karne en fazla beş rakam gösterir; fazlası artık bir değerlendirme gibi okunmaz.',
  'Laat de vorige rapportage leeg als er nog geen meting was; de slide toont dan geen verandering.':
      'Daha önce bir ölçüm yoksa önceki raporu boş bırakın; slayt o zaman hiçbir değişiklik göstermez.',
  'Bepaalt of een stijging groen of rood kleurt. De pijl volgt altijd de cijfers.':
      'Bir artışın yeşil mi kırmızı mı olacağını belirler. Ok her zaman rakamları izler.',
  'Een paar kerncijfers met het cijfer van de vorige rapportage ernaast, zodat de verandering het verhaal vertelt. Geef per cijfer aan of stijgen goed of slecht nieuws is.':
      'Yanında önceki raporun rakamı bulunan birkaç temel rakam; böylece hikâyeyi değişim anlatır. Her rakam için artışın iyi haber mi kötü haber mi olduğunu belirtin.',
  'Zekere vondsten als fout behandelen': 'Kesin bulguları hata olarak ele al',
  'Normaal is een zekere vondst — een BSN, een IBAN, een e-mailadres — een waarschuwing die je kunt negeren. Aan maakt er een fout van, en dan kan de export erop blokkeren als je die instelling ook aan hebt staan. Bedoeld voor omgevingen waar zulke gegevens er echt niet doorheen mogen. Onzekere vondsten blijven een waarschuwing.':
      'Normalde kesin bir bulgu — bir ulusal kimlik numarası, bir IBAN, bir e-posta adresi — göz ardı edebileceğiniz bir uyarıdır. Açık konumda bu bir hataya dönüşür ve ilgili ayar da açıksa dışa aktarma bunun üzerine engellenebilir. Bu tür verilerin gerçekten geçmemesi gereken ortamlar için tasarlanmıştır. Kesin olmayan bulgular uyarı olarak kalır.',
