  'Opgeslagen op deze computer, nog niet in de repository. Gaat mee zodra er weer verbinding is — of nu, met "Wachtrij legen".':
      'Bu bilgisayara kaydedildi, henüz repository\'ye değil. Bağlantı yeniden kurulur kurulmaz gönderilir — ya da hemen, "Kuyruğu boşalt" ile.',
