  'creditcardnummer': 'kredi kartı numarası',
  'beveiligingscode van een creditcard': 'kredi kartı güvenlik kodu (CVV)',
  'gegevens in de sprekersnotities — onzichtbaar op de slide, wél in de export':
      'sunucu notlarındaki veriler — slaytta görünmez, ama dışa aktarmada var',
  'Certificaat vertrouwen?': 'Sertifikaya güvenilsin mi?',
  'Het certificaat van deze server is niet ondertekend door een erkende uitgever. Dat is gewoon bij een zelf gehoste server, maar het is ook hoe een afgeluisterde verbinding eruitziet.':
      'Bu sunucunun sertifikası tanınmış bir sağlayıcı tarafından imzalanmamış. Kendi barındırdığınız bir sunucuda bu olağandır, ama dinlenen bir bağlantı da tam olarak böyle görünür.',
  'Vergelijk de vingerafdruk hieronder met wat je server zelf toont. Komen ze overeen, dan praat je met de juiste machine.':
      'Aşağıdaki parmak izini sunucunuzun kendi gösterdiğiyle karşılaştırın. Eşleşiyorlarsa doğru makineyle konuşuyorsunuz.',
  'Uitgegeven aan': 'Verilen',
  'Uitgegeven door': 'Veren',
  'Geldig tot': 'Geçerlilik bitişi',
  'Vingerafdruk (SHA-256)': 'Parmak izi (SHA-256)',
  'Alleen dit ene certificaat wordt vertrouwd. Vervangt de server het later, dan vraagt OciDeck het opnieuw.':
      'Yalnızca bu tek sertifikaya güvenilir. Sunucu onu daha sonra değiştirirse OciDeck yeniden sorar.',
  'Vertrouwen': 'Güven',
  'Certificaat bekijken': 'Sertifikayı görüntüle',
  'De plekken waar je presentaties bewaart en doorzoekt — mappen op deze computer, WebDAV-servers, S3-buckets en git-repositories door elkaar. Sleep ze in de volgorde die jij wilt: de bovenste van een soort geldt als standaard.':
      'Sunumlarınızı sakladığınız ve içinde arama yaptığınız yerler — bu bilgisayardaki klasörler, WebDAV sunucuları, S3 bucket\'ları ve git repository\'leri bir arada. İstediğiniz sıraya sürükleyin: bir türün en üsttekisi varsayılan sayılır.',
  '•  S3-opslag: verbind je met een bucket, dan worden het endpoint, de bucketnaam en je toegangssleutel bewaard (de geheime sleutel veilig in de sleutelbos van je systeem) en worden de presentaties die je opent of opslaat naar die opslagdienst verstuurd.':
      '•  S3 depolama: bir bucket\'a bağlandığınızda endpoint, bucket adı ve erişim anahtarınız saklanır (gizli anahtar güvenli biçimde sisteminizin anahtar zincirinde) ve açtığınız veya kaydettiğiniz sunumlar o depolama hizmetine gönderilir.',
  '•  Git-opslag: verbind je met een repository, dan wordt je toegangstoken bewaard (veilig in de sleutelbos van je systeem) en worden de presentaties die je opslaat als commits naar die server verstuurd. Een werkkopie van de repository blijft onversleuteld op dit apparaat staan.':
      '•  Git depolama: bir repository\'ye bağlandığınızda erişim belirteciniz saklanır (güvenli biçimde sisteminizin anahtar zincirinde) ve kaydettiğiniz sunumlar o sunucuya commit olarak gönderilir. Repository\'nin bir çalışma kopyası bu cihazda şifrelenmemiş olarak kalır.',
  'Voor de taal van dit deck ontbreken de ziekte- en aandoeningsnamen. Religie, politieke overtuiging en vakbondstermen worden wel herkend, en controlegetallen (BSN, IBAN, paspoort) werken altijd — maar reken er niet op dat een diagnose gevonden wordt.':
      'Bu sunumun dili için hastalık ve rahatsızlık adları eksik. Din, siyasi görüş ve sendika terimleri tanınır ve kontrol haneli desenler (ulusal kimlik numarası, IBAN, pasaport) her zaman çalışır — ama bir teşhisin bulunacağına güvenmeyin.',
  'niet getest': 'test edilmedi',
  'Werkte op': 'Çalıştığı tarih',
  'Je bent aangemeld, maar hebt hier geen toegang. Je wachtwoord is niet het probleem — vraag de beheerder om rechten op deze map.':
      'Oturumunuz açık, ancak burada erişiminiz yok. Sorun parolanız değil — bu klasör için yöneticiden yetki isteyin.',
  'Je token is geldig, maar mag dit niet. Geef het meer rechten, of wacht als de forge een limiet oplegt.':
      'Belirteciniz geçerli, ancak buna izni yok. Ona daha fazla yetki verin veya forge bir sınır uyguluyorsa bekleyin.',
  'Het token is geldig, maar mag dit niet — geef het meer rechten op de repository.':
      'Belirteç geçerli, ancak buna izni yok — ona repository üzerinde daha fazla yetki verin.',
  'Aangemeld, maar geen toegang — je wachtwoord is niet het probleem. Vraag rechten op deze map.':
      'Oturum açık, ama erişim yok — sorun parolanız değil. Bu klasör için yetki isteyin.',
  'Lexiconlicenties: wat er nog nagevraagd moet worden':
      'Sözlük lisansları: hâlâ sorulması gerekenler',
  'Dit lijkt een volledige DAV-URL. Bij Nextcloud leidt OciDeck dat pad zelf af — hier hoort alleen de server te staan.':
      'Bu, tam bir DAV URL\'si gibi görünüyor. Nextcloud\'da OciDeck bu yolu kendisi türetir — buraya yalnızca sunucu yazılır.',
  'Overnemen': 'Uygula',
  'WebDAV is niet (goed) ingesteld — controleer de servergegevens bij Instellingen → Opslag.':
      'WebDAV (düzgün) ayarlanmamış — sunucu bilgilerini Ayarlar → Depolama bölümünde denetleyin.',
  'De git-repository is niet (goed) ingesteld — controleer server, eigenaar en repository bij Instellingen → Opslag.':
      'Git repository\'si (düzgün) ayarlanmamış — sunucuyu, sahibi ve repository\'yi Ayarlar → Depolama bölümünde denetleyin.',
  'De servernaam van de forge bestaat niet, of is niet op te zoeken. Controleer de server-URL op een typefout.':
      'Forge\'un sunucu adı yok veya çözümlenemiyor. Sunucu URL\'sinde yazım hatası olup olmadığını denetleyin.',
  'Deze forge heeft een privé- of LAN-adres. Markeer hem als vertrouwd intern bij Instellingen → Opslag.':
      'Bu forge özel veya LAN adresine sahip. Ayarlar → Depolama bölümünde güvenilir dahili olarak işaretleyin.',
  'De forge is niet bereikbaar — controleer je verbinding en de server-URL.':
      'Forge\'a ulaşılamıyor — bağlantınızı ve sunucu URL\'sini denetleyin.',
  'Aanmelden bij de forge mislukt. Controleer je token: het heeft leesrechten op de repository nodig, en schrijfrechten om op te slaan.':
      'Forge\'da oturum açma başarısız. Belirtecinizi denetleyin: repository üzerinde okuma yetkisine, kaydetmek için de yazma yetkisine ihtiyacı var.',
  'Niet gevonden in de repository — of je token mag het niet zien.':
      'Repository\'de bulunamadı — ya da belirtecinizin bunu görme izni yok.',
  'De forge gaf een fout. Probeer het later opnieuw.':
      'Forge bir hata döndürdü. Daha sonra tekrar deneyin.',
  'Dit adres antwoordt niet als een forge. Klopt de soort forge bij Instellingen → Opslag?':
      'Bu adres bir forge gibi yanıt vermiyor. Ayarlar → Depolama bölümündeki forge türü doğru mu?',
  'Stel eerst een WebDAV-server in bij Instellingen → Opslag.':
      'Önce Ayarlar → Depolama bölümünde bir WebDAV sunucusu ayarlayın.',
  'Nodig wanneer de forge op een privé- of thuisnetwerk draait. Zonder deze vlag weigert de beveiliging een privé-adres.':
      'Forge özel bir ağda veya ev ağında çalışıyorsa gereklidir. Bu işaret olmadan güvenlik denetimi özel bir adresi reddeder.',
  'Vul server-URL, eigenaar en repository in':
      'Sunucu URL\'sini, sahibi ve repository\'yi girin',
  'de standaardbranch heet': 'varsayılan branch\'in adı',
  'die wordt voortaan gebruikt': 'bundan sonra o kullanılacak',
  'de repository is nog leeg; de eerste opslag vult hem':
      'repository henüz boş; ilk kayıt onu dolduracak',
  'let op: dit token mag alleen lezen, dus opslaan zal mislukken':
      'dikkat: bu belirteç yalnızca okuyabilir, bu yüzden kaydetme başarısız olacak',
  'Aanmelden mislukt — controleer het token. Het heeft leesrechten op de repository nodig, en schrijfrechten om te kunnen opslaan.':
      'Oturum açma başarısız — belirteci denetleyin. Repository üzerinde okuma yetkisine, kaydedebilmek için de yazma yetkisine ihtiyacı var.',
  'Repository niet gevonden — of je token mag hem niet zien. Controleer eigenaar en repositorynaam.':
      'Repository bulunamadı — ya da belirtecinizin onu görme izni yok. Sahibi ve repository adını denetleyin.',
  'Dit adres antwoordt niet als een forge. Klopt de soort forge die je hebt gekozen?':
      'Bu adres bir forge gibi yanıt vermiyor. Seçtiğiniz forge türü doğru mu?',
  'kenteken': 'araç plakası',
  'Voor de taal van dit deck is er geen trefwoordenlijst voor bijzondere persoonsgegevens. Patronen met een controlegetal (BSN, IBAN, paspoort) werken wel; woorden als "diagnose" of "verdachte" worden niet herkend.':
      'Bu sunumun dili için özel nitelikli kişisel verilere dair bir anahtar kelime listesi yok. Kontrol haneli desenler (ulusal kimlik numarası, IBAN, pasaport) çalışır; "teşhis" veya "şüpheli" gibi kelimeler tanınmaz.',
  'De trefwoordenlijst voor bijzondere persoonsgegevens is voor de taal van dit deck erg dun. Reken er niet op dat woorden als "diagnose" of "verdachte" gevonden worden.':
      'Özel nitelikli kişisel veriler için anahtar kelime listesi, bu sunumun dilinde çok zayıf. "teşhis" veya "şüpheli" gibi kelimelerin bulunacağına güvenmeyin.',
  'Landpakketten voor identificatienummers':
      'Kimlik numaraları için ülke paketleri',
  'Nummers als het BSN of het PESEL zijn landgebonden. Heel Europa staat aan omdat de meeste van die nummers een controlegetal hebben: die aanzetten kost vrijwel geen valse meldingen. IBAN, e-mail, geheimen en paspoortstroken staan hier los van en worden altijd nagekeken.':
      'BSN veya PESEL gibi numaralar ülkeye bağlıdır. Bu numaraların çoğu kontrol hanesi taşıdığı için tüm Avrupa açıktır: bunları açmak neredeyse hiç yanlış uyarıya yol açmaz. IBAN, e-posta, gizli bilgiler ve pasaport şeritleri bundan bağımsızdır ve her zaman denetlenir.',
