      'Metinde kişisel veriler, özel nitelikli veriler ve sırlar',
  'Slides, notities, tabellen, code, bestandspaden en URL\'s worden op dit apparaat doorzocht op identificerende nummers, financiële gegevens, contactgegevens, digitale identificatoren, geheimen, bijzondere persoonsgegevens (AVG art. 9/10), massagegevens en metadatalekken.':
      'Slaytlar, notlar, tablolar, kod, dosya yolları ve URL\'ler bu cihazda kimlik belirleyici numaralar, finansal veriler, iletişim bilgileri, dijital tanımlayıcılar, sırlar, özel nitelikli kişisel veriler (GDPR md. 9/10), toplu veriler ve meta veri sızıntıları açısından taranır.',
  'Alleen een zekere treffer waarschuwt; waarschijnlijk en mogelijk blijven informatief. Een uitgezette regel vuurt nergens.':
      'Yalnızca kesin bir eşleşme uyarı verir; muhtemel ve olası olanlar bilgilendirici kalır. Kapatılan bir kural hiçbir yerde tetiklenmez.',
  'Niet gecontroleerd: persoonsgegevens, bijzondere gegevens en geheimen. De privacycontrole staat uit bij Beveiliging.':
      'Denetlenmedi: kişisel veriler, özel nitelikli veriler ve sırlar. Gizlilik denetimi Güvenlik altında kapalı.',
