  'Weggelaten': 'Çıkarıldı',
  'Bewerkbaar': 'Düzenlenebilir',
  'De privacycontrole': 'Gizlilik denetimi',
  'OciDeck leest je dia\'s na op gegevens die privacygevoelig kunnen zijn: identificatienummers, contactgegevens, telefoonnummers, bankrekeningen, sleutels en wachtwoorden, en bijzondere persoonsgegevens. Dat gebeurt volledig op dit apparaat: er wordt niets verstuurd, en de gevonden waarde zelf komt in geen enkele melding te staan.':
      'OciDeck, slaytlarınızı gizlilik açısından hassas olabilecek veriler için gözden geçirir: kimlik numaraları, iletişim bilgileri, telefon numaraları, banka hesapları, anahtarlar ve parolalar ile özel nitelikli kişisel veriler. Bu tümüyle bu cihazda olur: hiçbir şey gönderilmez ve bulunan değerin kendisi hiçbir bildirimde yer almaz.',
  'De controle garandeert niet dat alles wordt gevonden; ze verkleint de kans dat er persoonsgegevens onbedoeld uitlekken.':
      'Denetim her şeyin bulunacağını garanti etmez; kişisel verilerin istemeden sızma olasılığını azaltır.',
  'Tekst in afbeeldingen blijft buiten beeld, gelinkte bestanden worden niet geopend, en gegevens zonder herkenbaar patroon herkent geen enkele scanner. Een dia zonder meldingen is een dia waarin wíj niets hebben gevonden, niet een dia waarvan vaststaat dat er niets in staat. Wat je deelt, blijft jouw beslissing en jouw verantwoordelijkheid.':
      'Görsellerdeki metin görüş alanı dışında kalır, bağlantı verilen dosyalar açılmaz ve tanınabilir bir deseni olmayan verileri hiçbir tarayıcı tanımaz. Bildirimi olmayan bir slayt, bizim içinde hiçbir şey bulamadığımız bir slayttır; içinde hiçbir şey olmadığı kesinleşmiş bir slayt değil. Neyi paylaştığınız sizin kararınız ve sizin sorumluluğunuzdur.',
  'telefoonnummer': 'telefon numarası',
  'Voor wie is deze export?': 'Bu dışa aktarma kimin için?',
  'Volledig': 'Tam',
  'Geredigeerd': 'Redakte edilmiş',
  'Voor de opdrachtgever of auditor: alleen wat je zelf op "weglaten" hebt gezet, gaat eruit. De rest blijft leesbaar, zodat een derde partij de bevindingen kan controleren.':
      'İşveren veya denetçi için: yalnızca kendinizin "çıkar" olarak işaretlediği kısımlar kaldırılır. Gerisi okunur kalır, böylece üçüncü bir taraf bulguları denetleyebilir.',
  'Voor de bredere kring: alles wat de controle vindt gaat eruit, ook op slides die je hebt geaccepteerd. Het bestand krijgt "-geredigeerd" in de naam.':
      'Daha geniş bir çevre için: denetimin bulduğu her şey kaldırılır, kabul ettiğiniz slaytlarda bile. Dosyanın adına "-geredigeerd" eklenir.',
  'tabel met persoonsgegevens (rijen×kolommen)':
