  'De CVE-lijst kon niet worden opgehaald. Controleer je verbinding en probeer het opnieuw; een half binnengehaalde lijst is weggegooid.':
      'CVE listesi alınamadı. Bağlantınızı denetleyip yeniden deneyin; yarım indirilmiş liste atıldı.',
  'De nieuwste uitgave opzoeken…': 'En yeni sürüm aranıyor…',
  'Dit is een grote download: ruim 500 MB binnenhalen, tijdelijk zo\'n 1,5 GB schijfruimte, en afhankelijk van je verbinding en apparaat al gauw tien tot dertig minuten werk. Daarna blijft er een index van enkele honderden megabytes staan. Op een verbinding die per megabyte betaalt, doe je dit liever niet.':
      'Bu büyük bir indirmedir: 500 MB\'ın üzerinde veri, geçici olarak yaklaşık 1,5 GB disk alanı ve bağlantınıza ve cihazınıza bağlı olarak kolayca on ila otuz dakikalık iş. Sonrasında birkaç yüz megabaytlık bir dizin geride kalır. Megabayt başına ücretlendirilen bir bağlantıda bunu yapmamanız daha iyi olur.',
  'Er was te weinig schijfruimte. De opbouw vraagt tijdelijk ruim 1,5 GB.':
      'Disk alanı yetersizdi. Dizinin oluşturulması geçici olarak 1,5 GB\'ın üzerinde alan ister.',
  'Het opgehaalde archief was niet wat we verwachtten en is geweigerd. Er is niets geïnstalleerd.':
      'Alınan arşiv beklediğimiz gibi değildi ve reddedildi. Hiçbir şey kurulmadı.',
  'Indexeren…': 'Dizinleniyor…',
  'Lokaal beschikbaar — opzoeken gebeurt offline, er gaat geen zoekterm naar buiten.':
      'Yerel olarak kullanılabilir — aramalar çevrimdışı yapılır, hiçbir arama terimi dışarı çıkmaz.',
  'Lokale CVE-database': 'Yerel CVE veritabanı',
  'Met de CVE-lijst op je eigen apparaat blijft het opzoeken hier: er gaat geen zoekterm meer naar een server, en niemand kan zien welk lek je onderzoekt.':
      'CVE listesi kendi cihazınızda olduğunda aramalar burada kalır: artık hiçbir arama terimi bir sunucuya gitmez ve hangi açığı incelediğinizi kimse göremez.',
  'Uitpakken…': 'Arşivden çıkarılıyor…',
  'Zet de volledige CVE-lijst op dit apparaat, zodat opzoeken offline gebeurt en je zoekterm nergens heen gaat. De database komt van CVE List V5 (het officiële CVE-programma, via GitHub).':
      'Tam CVE listesini bu cihaza yerleştirin; böylece aramalar çevrimdışı yapılır ve arama teriminiz hiçbir yere gitmez. Veritabanı CVE List V5\'ten gelir (resmî CVE programı, GitHub üzerinden).',
  'Wat er lokaal beschikbaar is': 'Yerel olarak neler kullanılabilir',
  'Gegevenspakket': 'Veri paketi',
  'Nu bijwerken': 'Şimdi güncelle',
  'Gegevens lokaal beschikbaar — het opzoeken gebeurt op dit apparaat, er gaat niets naar buiten.':
      'Veriler yerel olarak kullanılabilir — aramalar bu cihazda yapılır, dışarı hiçbir şey çıkmaz.',
  'Zwakheden (CWE)': 'Zayıflıklar (CWE)',
  'Testgevallen (WSTG)': 'Test durumları (WSTG)',
  'MIAUW-eisen': 'MIAUW gereksinimleri',
  'CVSS-scoretabel': 'CVSS puan tablosu',
  'Bevindingsjablonen': 'Bulgu şablonları',
  'Zoek een instelling': 'Bir ayar arayın',
  'Geen instelling gevonden': 'Ayar bulunamadı',
  'Je zoekterm gaat naar de ingestelde CVE-mirror, en als die niets vindt ook naar ENISA en MITRE. Wie die servers beheert, kan daaruit afleiden naar welk specifiek lek je zoekt — en dus welk lek je onderzoekt.':
      'Arama teriminiz ayarlanan CVE aynasına, orada bir şey bulunmazsa ENISA ve MITRE\'ye de gider. Bu sunucuları işletenler, buradan hangi belirli açığı aradığınızı — dolayısıyla hangi açığı incelediğinizi — çıkarabilir.',
  'Accepteren': 'Kabul et',
  'Accepteren + waarschuwen': 'Kabul et + uyar',
  'Accepteren: de gegevens horen hier en de melding verdwijnt. Accepteren + waarschuwen: de ontvanger ziet een badge dat er persoonsgegevens op de slide staan. Weglaten: de gevonden gegevens worden onleesbaar gemaakt op het scherm en in de export — je markdown-bestand houdt de oorspronkelijke tekst.':
      'Kabul et: veriler buraya aittir ve bildirim kaybolur. Kabul et + uyar: alıcı, slaytta kişisel veri bulunduğunu belirten bir rozet görür. Çıkar: bulunan veriler ekranda ve dışa aktarmada okunamaz hâle getirilir — Markdown dosyanız özgün metni korur.',
  'Alleen melden': 'Yalnızca bildir',
  'PERSOONSGEGEVENS': 'KİŞİSEL VERİLER',
  'Persoonsgegevens op deze slide': 'Bu slayttaki kişisel veriler',
  'Volg de presentatie': 'Sunumu takip et',
  'Weglaten uit tonen en exporteren': 'Gösterimden ve dışa aktarmadan çıkar',
  ' Overweeg dit te redigeren met [[dubbele blokhaken]].':
      ' Bunu [[çift köşeli parantez]] ile redakte etmeyi düşünün.',
  ' Zonder context in de tekst is dit mogelijk geen persoonsgegeven.':
      ' Metinde bağlam olmadan bu bir kişisel veri olmayabilir.',
  'Leest je dia\'s na op identificatienummers, contactgegevens en andere privacygevoelige gegevens, en meldt ze bij de kwaliteitscontrole. Dit gebeurt volledig op dit apparaat; er wordt niets verstuurd. Het is een hulpmiddel, geen garantie: tekst in afbeeldingen en gegevens zonder herkenbaar patroon blijven buiten beeld.':
      'Slaytlarınızı kimlik numaraları, iletişim bilgileri ve gizlilik açısından hassas diğer veriler için gözden geçirir ve bunları kalite denetiminde bildirir. Bu tümüyle bu cihazda olur; hiçbir şey gönderilmez. Bu bir yardımcıdır, garanti değil: görsellerdeki metin ve tanınabilir deseni olmayan veriler görüş alanı dışında kalır.',
  'Mogelijk persoonsgegeven': 'Olası kişisel veri',
  'Privacycontrole': 'Gizlilik denetimi',
  'Waarschuw bij mogelijke persoonsgegevens': 'Olası kişisel verilerde uyar',
  'burgerservicenummer (BSN)': 'vatandaşlık hizmet numarası (BSN)',
  'bankrekeningnummer (IBAN)': 'banka hesap numarası (IBAN)',
  'e-mailadres': 'e-posta adresi',
  'De TSA-handtekening is niet in-app geverifieerd; alleen de hash komt overeen.':
      'TSA imzası uygulama içinde doğrulanmadı; yalnızca özet (hash) eşleşiyor.',
  'Extern': 'Harici',
  'Van een externe URL opgehaald; het openen heeft die server benaderd.':
      'Harici bir URL\'den alındı; açılması o sunucuya erişti.',
  'AI-assistentie (staat standaard uit): kies je een zelf-gehoste of cloud-backend, dan worden de teksten of afbeeldingen die je laat verwerken naar dat adres gestuurd. Wat je hebt geredigeerd, gaat er eerst uit. Een lokaal AI-model op dit apparaat verstuurt niets.':
      'Yapay zekâ desteği (varsayılan olarak kapalı): kendi barındırdığınız bir arka uç ya da bulut arka ucu seçerseniz, işlenmesini istediğiniz metinler veya görseller o adrese gönderilir. Redakte ettikleriniz önce çıkarılır. Bu cihazdaki yerel bir yapay zekâ modeli hiçbir şey göndermez.',
  'Gegevens weglaten (redactie)': 'Verileri çıkarma (redaksiyon)',
  'Zet je tekst tussen dubbele blokhaken, zoals [[het adres]], dan laat OciDeck die weg uit alles wat je toont en exporteert. Op de dia, in de presentatie, in de PDF, de PowerPoint en de HTML verschijnen alleen blokken.':
      'Metni [[adres]] gibi çift köşeli parantez içine alırsanız, OciDeck onu gösterdiğiniz ve dışa aktardığınız her şeyden çıkarır. Slaytta, sunumda, PDF\'te, PowerPoint\'te ve HTML\'de yalnızca bloklar görünür.',
  'Weggelaten is écht weggelaten, niet afgedekt. De tekst zit niet als onzichtbare laag onder een zwart balkje in de PDF, niet in de sprekersnotities van de PowerPoint, en niet in de broncode van de HTML. Wie het bestand openmaakt, kan er niets uit terughalen.':
      'Çıkarılan gerçekten çıkarılmıştır, üzeri örtülmüş değildir. Metin, PDF\'te siyah bir çubuğun altında görünmez bir katman olarak durmaz, PowerPoint\'in sunucu notlarında yer almaz ve HTML\'in kaynak kodunda bulunmaz. Dosyayı açan kimse ondan hiçbir şey geri getiremez.',
  'Je eigen bestand verandert niet. De oorspronkelijke tekst blijft in je markdown staan; redactie geldt alleen voor wat je deelt. Zo houd je je eigen gegevens.':
      'Kendi dosyanız değişmez. Özgün metin Markdown dosyanızda kalır; redaksiyon yalnızca paylaştığınız için geçerlidir. Böylece kendi verileriniz sizde kalır.',
