  'Te weinig contrast met de achtergrond — mogelijk onleesbaar.':
      'Arka planla kontrast çok düşük — okunamayabilir.',
  'Ik ga akkoord met de EUPL 1.2-licentie en heb gelezen welke gegevens OciDeck bewaart.':
      'EUPL 1.2 lisansını kabul ediyorum ve OciDeck\'in hangi verileri sakladığını okudum.',
  'Je keuze wordt de standaardtaal van de app.':
      'Seçiminiz uygulamanın varsayılan dili olur.',
  'Lees de volledige licentie': 'Lisansın tamamını okuyun',
  'OciDeck is vrije software onder de EUPL 1.2-licentie. Voordat je begint, vragen we je de licentie te accepteren. Hieronder lees je ook welke gegevens OciDeck op dit apparaat bewaart en wanneer er iets je apparaat verlaat.':
      'OciDeck, EUPL 1.2 lisansı altında özgür yazılımdır. Başlamadan önce lisansı kabul etmenizi rica ediyoruz. Aşağıda ayrıca OciDeck\'in bu cihazda hangi verileri sakladığını ve ne zaman bir şeyin cihazınızdan ayrıldığını okuyabilirsiniz.',
  'OciDeck verzamelt geen statistieken en stuurt uit zichzelf niets naar buiten. Standaard blijft alles op dit apparaat. Gegevens verlaten dit apparaat alleen als jij dat kiest:\n\n•  Nextcloud/WebDAV: verbind je met een server, dan worden je inlognaam en wachtwoord bewaard (het wachtwoord veilig in de sleutelbos van je systeem) en worden de presentaties die je opent of opslaat naar die server verstuurd.\n•  Openen via URL: OciDeck haalt het bestand op van het adres dat je invoert.\n•  Online media (staat standaard uit): indien ingeschakeld laadt OciDeck afbeeldingen en video\'s van de adressen in je dia\'s.\n•  Externe links (zoals de online licentie) openen in je browser.':
      'OciDeck istatistik toplamaz ve kendiliğinden dışarıya hiçbir şey göndermez. Varsayılan olarak her şey bu cihazda kalır. Veriler bu cihazdan yalnızca siz öyle seçerseniz ayrılır:\n\n•  Nextcloud/WebDAV: bir sunucuya bağlanırsanız kullanıcı adınız ve parolanız saklanır (parola, sisteminizin anahtar zincirinde güvenli biçimde) ve açtığınız veya kaydettiğiniz sunumlar o sunucuya gönderilir.\n•  URL ile açma: OciDeck dosyayı girdiğiniz adresten alır.\n•  Çevrimiçi ortam (varsayılan olarak kapalı): etkinleştirildiğinde OciDeck, slaytlarınızdaki adreslerden görselleri ve videoları yükler.\n•  Harici bağlantılar (çevrimiçi lisans gibi) tarayıcınızda açılır.',
  'OciDeck wordt geleverd onder de European Union Public Licence v1.2. Door akkoord te gaan aanvaard je deze licentie. Je mag OciDeck gebruiken, kopiëren, aanpassen en verspreiden onder de voorwaarden van de EUPL 1.2.':
      'OciDeck, European Union Public Licence v1.2 altında sunulur. Kabul ederek bu lisansı benimsemiş olursunuz. OciDeck\'i EUPL 1.2 koşulları altında kullanabilir, kopyalayabilir, değiştirebilir ve dağıtabilirsiniz.',
  'Om te werken en je werk niet te verliezen, bewaart OciDeck gegevens lokaal op dit apparaat:\n\n•  Je instellingen en voorkeuren (taal, mappen, stijl- en weergaveprofielen, recente bestanden).\n•  Je presentatiematerialen: de presentaties die je opslaat, automatische herstelkopieën en bijlagen zoals afbeeldingsbeschrijvingen.\n•  Deze toestemmingskeuze.\n\nJe kunt dit verwijderen door de bestanden te wissen of de instellingen te resetten.':
      'Çalışabilmek ve işinizi kaybetmemek için OciDeck verileri bu cihazda yerel olarak saklar:\n\n•  Ayarlarınız ve tercihleriniz (dil, klasörler, stil ve görünüm profilleri, son kullanılan dosyalar).\n•  Sunum malzemeleriniz: kaydettiğiniz sunumlar, otomatik kurtarma kopyaları ve görsel açıklamaları gibi ekler.\n•  Bu izin seçimi.\n\nBunları dosyaları silerek veya ayarları sıfırlayarak kaldırabilirsiniz.',
